// Ported from the Node app's Sequelize model Hostel (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class HostelConfiguration : IEntityTypeConfiguration<Hostel>
{
    public void Configure(EntityTypeBuilder<Hostel> builder)
    {
        builder.ToTable("hostels", t =>
        {
            t.HasCheckConstraint("CK_hostels_type", "[type] IN (N'boys', N'girls', N'mixed')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(80)").HasMaxLength(80).IsRequired();
        builder.Property(e => e.Type).HasColumnName("type").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'boys'");
        builder.Property(e => e.WardenName).HasColumnName("warden_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.WardenPhone).HasColumnName("warden_phone").HasColumnType("nvarchar(30)").HasMaxLength(30);
        builder.Property(e => e.Address).HasColumnName("address").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.HasIndex(e => e.Name).IsUnique();
    }
}
